import * as pdfjsLib from 'pdfjs-dist';

// Set the workerSrc globally to avoid issues with the PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      const typedArray = new Uint8Array(reader.result);
      const pdf = await pdfjsLib.getDocument(typedArray).promise;

      let parsedText = '';

      // Loop through all the pages
      for (let i = 0; i < pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const textContent = await page.getTextContent();

        // Extract text from each page
        const pageText = textContent.items.map((item) => item.str).join(' ');
        parsedText += pageText + '\n';
      }

      // Once text is parsed, organize into sections
      const organizedText = organizeResumeText(parsedText);
      resolve(organizedText);
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

// Function to organize parsed text into sections
const organizeResumeText = (parsedText) => {
  const sections = {};

  // Define regex patterns for different sections
  const sectionPatterns = {
    contact: /(.*Champaign, IL.*|.*linkedin.com.*)/, // Custom pattern for contact details
    education: /EDUCATION\s*(.*?)\s*(?=(EXPERIENCE|PROJECTS|SKILLS|$))/s,
    experience: /EXPERIENCE\s*(.*?)\s*(?=(EDUCATION|PROJECTS|SKILLS|$))/s,
    projects: /PROJECTS\s*(.*?)\s*(?=(EXPERIENCE|EDUCATION|SKILLS|$))/s,
    skills: /SKILLS\s*(.*)/s,  // Capture everything under SKILLS until the end
  };

  // Extract sections using regex
  for (const [section, pattern] of Object.entries(sectionPatterns)) {
    const match = parsedText.match(pattern);
    if (match) {
      sections[section] = match[1].trim(); // Capture the content under each section
    }
  }

  return sections;
};

export { parsePDF };
